package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;

/** Bounded administrator-owned state policies, with one retained lifecycle per record. */
final class ConditionalClocks {
 private ConditionalClocks() {}
 static final List<String> ACTIONS=List.of("start","pause","complete","cancel");
 static Map<String,Object> definition(Store.Db db,Object input)throws SQLException {
  var body=object(input);require(body.keySet().equals(Set.of("name","table","calendar","minutes","purpose","max_priority","start","pause","complete","cancel")),"Provide name, table, calendar, budget, purpose, priority and four state lists");
  String name=WorkJobs.text(body.get("name"),160),table=WorkJobs.text(body.get("table"),80),calendar=WorkJobs.text(body.get("calendar"),80),purpose=WorkJobs.text(body.get("purpose"),20);var schema=Service.schema(db,table);RecordPolicy.require(schema,"read",db.viewerRole);var states=object(schema.get("states"));require(!states.isEmpty(),"Choose a table with defined states");require(Set.of("general","response","resolution").contains(purpose),"Choose a supported clock purpose");require(body.get("minutes") instanceof Integer n && n>0 && n<=525600,"Use1–525600 business minutes");require(body.get("max_priority") instanceof Integer n && n>=0 && n<=5,"Use maximum priority0–5");int priority=(Integer)body.get("max_priority");require(priority==0 || object(schema.get("fields")).containsKey("priority"),"This table has no priority field");require(db.count("SELECT COUNT(*) FROM os_calendar WHERE calendar_id=?",calendar)==1,"Choose an existing business calendar");var result=map("name",name,"table",table,"calendar",calendar,"minutes",body.get("minutes"),"purpose",purpose,"max_priority",priority);var seen=new HashSet<String>();
  for(String action:ACTIONS){require(body.get(action) instanceof List<?> list && list.size()<=100,"Use bounded state lists");var selected=new ArrayList<String>();for(Object state:(List<?>)body.get(action)){require(state instanceof String && states.containsKey(state) && seen.add((String)state),"Choose current non-overlapping states");selected.add((String)state);}Collections.sort(selected);result.put(action,selected);}require(!((List<?>)result.get("start")).isEmpty(),"Choose at least one start state");return result;
 }
 static Map<String,Object> owner(Store.Db db,Map<String,Object> policy)throws SQLException {
  var owner=db.one("SELECT * FROM os_user WHERE user_id=? AND active=1 AND role='admin'",policy.get("owner_id"));return owner==null || PasswordReset.required(owner)?null:owner;
 }
 static Map<String,Object> page(Store.Db db,String id,Map<String,String> args)throws SQLException {
  Service.requireAccountAdministrator(db,db.viewerId);require(Set.of("table").containsAll(args.keySet()),"Choose only a table");var policy=id.isEmpty()?null:db.one("SELECT * FROM os_clock_policy WHERE policy_id=?",id);if(!id.isEmpty() && policy==null)throw new Failure(404,"Clock policy not found");String table=policy==null?args.getOrDefault("table","incident"):policy.get("table_name").toString();var schema=Service.schema(db,table);RecordPolicy.require(schema,"read",db.viewerRole);var policies=db.all("SELECT * FROM os_clock_policy ORDER BY name,policy_id");for(var row:policies)row.put("authority",owner(db,row)==null?"owner_unavailable":RecordPolicy.allows(Service.schema(db,row.get("table_name").toString()),"read","admin")?"ready":"table_read_unavailable");var tables=new ArrayList<Map<String,Object>>();for(var row:db.all("SELECT name,definition FROM os_schema ORDER BY name"))if(!object(object(row.get("definition")).get("states")).isEmpty())tables.add(map("name",row.get("name"),"label",object(row.get("definition")).get("label")));var definition=policy==null?map("name","","table",table,"calendar","","minutes",120,"purpose","general","max_priority",0,"start",List.of(),"pause",List.of(),"complete",List.of(),"cancel",List.of()):object(policy.get("definition"));var stateRows=new ArrayList<Map<String,Object>>();for(var state:object(schema.get("states")).entrySet()){String selected="ignore";for(String action:ACTIONS)if(((List<?>)definition.get(action)).contains(state.getKey()))selected=action;stateRows.add(map("code",state.getKey(),"label",state.getValue(),"action",selected));}return map("policies",policies,"policy",policy==null?map("policy_id","","revision",0,"active",1):policy,"definition",definition,"states",stateRows,"tables",tables,"calendars",db.all("SELECT calendar_id FROM os_calendar ORDER BY calendar_id"),"used",!id.isEmpty() && db.count("SELECT COUNT(*) FROM os_clock_binding WHERE policy_id=? AND sla_id<>''",id)>0);
 }
 static Map<String,Object> form(Store.Db db,Map<String,String> input)throws SQLException {
  var form=new LinkedHashMap<>(input);form.remove("csrf");if(form.keySet().equals(Set.of("revision","active"))){require(Set.of("true","false").contains(form.get("active")),"Choose policy availability");return map("revision",Service.number(form.get("revision"),0,Integer.MAX_VALUE),"active",Boolean.valueOf(form.get("active")));}var fields=new HashSet<>(Set.of("name","table","calendar","minutes","purpose","max_priority","active","revision"));String table=form.getOrDefault("table","");var states=object(Service.schema(db,table).get("states"));for(String state:states.keySet())fields.add("state_"+state);require(form.keySet().equals(fields),"Provide current policy fields and state choices");require(Set.of("true","false").contains(form.get("active")),"Choose policy availability");var definition=map("name",form.get("name"),"table",table,"calendar",form.get("calendar"),"minutes",Service.number(form.get("minutes"),1,525600),"purpose",form.get("purpose"),"max_priority",Service.number(form.get("max_priority"),0,5));for(String action:ACTIONS)definition.put(action,new ArrayList<String>());for(String state:states.keySet()){String action=form.get("state_"+state);require(action.equals("ignore") || ACTIONS.contains(action),"Choose a supported state action");if(!action.equals("ignore"))((List<String>)definition.get(action)).add(state);}return map("revision",Service.number(form.get("revision"),0,Integer.MAX_VALUE),"active",Boolean.valueOf(form.get("active")),"definition",definition);
 }
 static Map<String,Object> save(Store.Db db,String id,Object input)throws SQLException {
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);require((body.keySet().equals(Set.of("revision","active","definition")) || body.keySet().equals(Set.of("revision","active"))) && body.get("active") instanceof Boolean,"Provide revision, Boolean active and definition");var before=id.isEmpty()?null:db.one("SELECT * FROM os_clock_policy WHERE policy_id=?",id);if(!id.isEmpty() && before==null)throw new Failure(404,"Clock policy not found");ProblemInvestigations.revision(body.get("revision"),before==null?0:before.get("revision"));require(before!=null || body.containsKey("definition"),"A new policy requires its definition");var definition=body.containsKey("definition")?definition(db,body.get("definition")):object(before.get("definition"));if(before!=null && db.count("SELECT COUNT(*) FROM os_clock_binding WHERE policy_id=? AND sla_id<>''",id)>0 && !object(before.get("definition")).equals(definition))throw new Failure(409,"A used policy keeps its original meaning; create a replacement");int revision=before==null?1:((Number)before.get("revision")).intValue()+1,active=Boolean.TRUE.equals(body.get("active"))?1:0;if(before==null){require(db.count("SELECT COUNT(*) FROM os_clock_policy")<100,"At most100 clock policies are supported");id=Values.id();db.update("INSERT INTO os_clock_policy(policy_id,name,table_name,definition,active,revision,owner_id) VALUES(?,?,?,?,?,?,?)",id,definition.get("name"),definition.get("table"),JSON.writeValueAsString(definition),active,revision,db.viewerId);}else db.update("UPDATE os_clock_policy SET name=?,table_name=?,definition=?,active=?,revision=? WHERE policy_id=?",definition.get("name"),definition.get("table"),JSON.writeValueAsString(definition),active,revision,id);SecurityEvents.record(db,db.viewerId,db.viewerId,"sla.policy_saved",map("policy_id",id,"revision",revision,"active",active));return page(db,id,Map.of());
 }
 static void receipt(Store.Db db,Map<String,Object> policy,Map<String,Object> item,String clock,Map<String,Object> definition,String action,long now)throws SQLException {
  definition=new LinkedHashMap<>(definition);definition.putIfAbsent("policy_revision",policy.get("revision"));String id=policy.get("policy_id").toString(),record=item.get("sys_id").toString();var before=db.one("SELECT revision,last_outcome FROM os_clock_binding WHERE policy_id=? AND record_id=?",id,record);if(before!=null && before.get("last_outcome").equals(action))return;int revision=before==null?1:((Number)before.get("revision")).intValue()+1;db.update("INSERT INTO os_clock_binding(policy_id,record_id,sla_id,definition,revision,last_outcome) VALUES(?,?,?,?,?,?) ON CONFLICT(policy_id,record_id) DO UPDATE SET sla_id=excluded.sla_id,definition=excluded.definition,revision=excluded.revision,last_outcome=excluded.last_outcome",id,record,clock,JSON.writeValueAsString(definition),revision,action);db.update("INSERT INTO os_clock_transition(policy_id,record_id,revision,detail) VALUES(?,?,?,?)",id,record,revision,JSON.writeValueAsString(map("action",action,"at",ServiceOutages.stamp(now),"policy_revision",definition.get("policy_revision"),"record_revision",item.get("revision"),"sla_id",clock)));db.update("DELETE FROM os_clock_transition WHERE policy_id=? AND record_id=? AND revision<=?",id,record,revision-100);
 }
 static void changed(Store.Db db,Map<String,Object> item,long now)throws SQLException {
  String originalId=db.viewerId,originalRole=db.viewerRole;boolean portal=db.employeePortal;
  try{for(var policy:db.all("SELECT * FROM os_clock_policy WHERE table_name=? ORDER BY policy_id",item.get("table"))){var binding=db.one("SELECT * FROM os_clock_binding WHERE policy_id=? AND record_id=?",policy.get("policy_id"),item.get("sys_id"));boolean attached=binding!=null && !binding.get("sla_id").toString().isEmpty();if(!attached && ((Number)policy.get("active")).intValue()==0)continue;var owner=owner(db,policy);if(owner==null)continue;db.viewerId=owner.get("user_id").toString();db.viewerRole="admin";db.employeePortal=false;if(!SlaAlerts.visible(db,owner,item))continue;var definition=attached?object(binding.get("definition")):object(policy.get("definition"));var data=object(item.get("data"));String state=Objects.toString(data.get("state"),"");boolean complete=((List<?>)definition.get("complete")).contains(state),cancel=((List<?>)definition.get("cancel")).contains(state),pause=((List<?>)definition.get("pause")).contains(state);
    if(!attached){int priority=((Number)definition.get("max_priority")).intValue();if(complete || cancel || !((List<?>)definition.get("start")).contains(state) || (priority>0 && !List.of("1","2","3","4","5").subList(0,priority).contains(data.get("priority"))))continue;String purpose=definition.get("purpose").toString();if(!purpose.equals("general") && db.count("SELECT COUNT(*) FROM os_sla WHERE table_name=? AND record_id=? AND purpose=? AND state IN ('running','paused')",item.get("table"),item.get("sys_id"),purpose)>0){receipt(db,policy,item,"",definition,"blocked_by_active_purpose",now);continue;}if(db.count("SELECT COUNT(*) FROM os_calendar WHERE calendar_id=?",definition.get("calendar"))==0){receipt(db,policy,item,"",definition,"calendar_unavailable",now);continue;}var clock=ServiceClocks.start(db,db.viewerId,map("table",item.get("table"),"record_id",item.get("sys_id"),"calendar",definition.get("calendar"),"minutes",definition.get("minutes"),"purpose",purpose),now);receipt(db,policy,item,clock.get("sla_id").toString(),definition,"attached",now);continue;}
    String id=binding.get("sla_id").toString();var clock=db.one("SELECT * FROM os_sla WHERE sla_id=?",id);if(clock==null || Set.of("completed","cancelled").contains(clock.get("state")))continue;String target=complete?"completed":cancel?"cancelled":pause?"paused":"running";if(clock.get("state").equals(target) || (clock.get("state").equals("breached") && !complete && !cancel))continue;ServiceClocks.advance(db,clock,now);var advanced=db.one("SELECT * FROM os_sla WHERE sla_id=?",id);if(advanced.get("state").equals("breached") && !complete && !cancel)continue;db.update("UPDATE os_sla SET state=?,last_tick=? WHERE sla_id=?",target,Math.max(now,((Number)clock.get("last_tick")).longValue()),id);receipt(db,policy,item,id,definition,target,now);
   }}finally{db.viewerId=originalId;db.viewerRole=originalRole;db.employeePortal=portal;}
 }
 static List<Map<String,Object>> history(Store.Db db,String table,String record)throws SQLException {
  Service.readRecord(db,table,record);var rows=db.all("SELECT b.*,p.name FROM os_clock_binding b JOIN os_clock_policy p ON p.policy_id=b.policy_id WHERE b.record_id=? ORDER BY p.name,p.policy_id",record);for(var row:rows){row.remove("definition");row.put("history",db.all("SELECT revision,detail FROM os_clock_transition WHERE policy_id=? AND record_id=? ORDER BY revision DESC",row.get("policy_id"),record));}return rows;
 }
}
